<script lang="ts">export let resourceName='';export let accessMode:'direct'|'agent'='direct';export let url='';export let mcpServerName='';export let testBusy=false;export let testStatus='';export let testMessage='';export let testError='';export let testLatency=0;export let onSubmit=()=>{};</script><form class="provider-summary docker-summary" on:submit|preventDefault={onSubmit}><div><span>RabbitMQ 资源</span><strong>{resourceName}</strong></div><div><span>接入方式</span><strong>{accessMode==='agent'?'Agent · MCP 代理':'Direct · Management API'}</strong><small>{accessMode==='agent'?mcpServerName||'未选择 MCPServer':url||'未设置 API 地址'}</small></div><div><span>连接核验</span>{#if testBusy}<strong>正在测试连接...</strong>{:else if testStatus==='succeeded'}<strong class="success">连接正常 · {testLatency} ms</strong><small>{testMessage}</small>{:else if testError}<strong class="failed">连接失败</strong><small>{testError}</small>{:else}<strong>尚未核验</strong>{/if}</div></form>
